import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        solve(1, in, out);
        out.close();
    }

    static void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        long k = in.nextLong();
        if (k == 0) {
            out.println(Mod998.fact(n));
            return;
        }

        if (k > n - 1) {
            out.println(0);
            return;
        }

        int c = (int) (n - k);

        long answer = 0;
        for (int i = 1; i <= c; i++) {
            answer = Mod998.add(answer, Mod998.mult(Mod998.paritySign(c - i), Mod998.ncr(c, i), Mod998.pow(i, n)));
        }

        answer = Mod998.mult(answer, 2, Mod998.ncr(n, c));
        out.println(answer);
    }

    static class Mod998 {
        private static final long MOD = 998_244_353L;
        private static final ArrayList<Long> factorial = new ArrayList<>();
        private static final ArrayList<Long> invFactorial = new ArrayList<>();

        static {
            factorial.add(1L);
            invFactorial.add(1L);
        }

        public static long modulus() { return MOD; }

        public static long fact(int n) {
            while (factorial.size() <= n) {
                factorial.add(mult(factorial.get(factorial.size() - 1), factorial.size()));
            }
            return factorial.get(n);
        }

        public static long fInv(int n) {
            int lastKnown = invFactorial.size() - 1;
            if (lastKnown < n) {
                long[] fInv = new long[n - lastKnown];
                fInv[0] = inv(fact(n));
                for (int i = 1; i < fInv.length; i++) {
                    fInv[i] = mult(fInv[i - 1], n - i + 1);
                }
                for (int i = fInv.length - 1; i >= 0; i--) {
                    invFactorial.add(fInv[i]);
                }
            }
            return invFactorial.get(n);
        }

        public static long paritySign(long k) {
            return (k & 1) == 0 ? 1 : MOD - 1;
        }

        public static long ncr(int n, int r) {
            if (r < 0 || n < r) return 0;
            return mult(fact(n), mult(fInv(r), fInv(n - r)));
        }

        public static long add(long a, long b) {
            long v = a + b;
            return v < MOD ? v : v - MOD;
        }

        public static long mult(long... x) {
            long r = 1;
            for (long i : x) r = mult(r, i);
            return r;
        }

        public static long mult(long a, long b) {
            return (a * b) % MOD;
        }

        public static long pow(long x, int e) {
            if (e < 0) {
                x = inv(x);
                e = -e;
            }
            if (e == 0) return 1;
            if ((e & 1) != 0) return mult(x, pow(x, e - 1));
            return pow(mult(x, x), e / 2);
        }

        public static long inv(long value) {
            long g = MOD, x = 0, y = 1;
            for (long r = value; r != 0; ) {
                long q = g / r;
                g %= r;
                long temp = g; g = r; r = temp;
                x -= q * y;
                temp = x; x = y; y = temp;
            }
            if (!(g == 1)) throw new AssertionError();
            if (!(y == MOD || y == -MOD)) throw new AssertionError();
            x %= MOD;
            if (x < 0) x += MOD;
            return x;
        }
    }

    static class InputReader {
        public final BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}
